<section class="overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900"><div class="border-b border-gray-100 px-6 py-5 dark:border-slate-800"><span class="text-xs font-semibold uppercase tracking-wider text-gray-400">SMS Center</span><h2 class="mt-0.5 text-lg font-bold text-gray-900 dark:text-white">Compose Broadcast</h2></div><div class="space-y-6 p-6"><div class="grid grid-cols-1 gap-4 md:grid-cols-2"><label><span class="mb-2 block text-xs font-semibold uppercase tracking-wider text-gray-500">Select Barangay</span><select x-model="selectedBarangay" class="w-full rounded-xl border border-gray-200 bg-white px-4 py-3 text-sm text-gray-800 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"><option>All Barangays</option>@foreach (['Bagbaguin','Balasing','Buenavista','Bulac','Camangyanan','Catmon','Caypombo','Caysio','Guyong','Lalakhan','Mag-asawang Sapa','Mahabang Parang','Manggahan','Parada','Poblacion','Pulong Buhangin','San Gabriel','San Jose Patag','San Vicente','Santa Clara','Santa Cruz','Silangan','Tabing Bakod','Tumana'] as $barangay)<option>{{ $barangay }}</option>@endforeach</select></label><label><span class="mb-2 block text-xs font-semibold uppercase tracking-wider text-gray-500">Select Status</span><select x-model="selectedStatus" class="w-full rounded-xl border border-gray-200 bg-white px-4 py-3 text-sm text-gray-800 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"><option>All Seniors</option><option>Active</option><option>Bedridden</option><option>Confined</option><option>Proxy / Representative</option></select></label></div><div><span class="mb-2.5 block text-xs font-semibold uppercase tracking-wider text-gray-500">Quick Templates</span><div class="flex flex-wrap gap-2"><template x-for="template in Object.keys(templates)" :key="template"><button type="button" @click="activeTemplate = template; messageText = templates[template]" :class="activeTemplate === template ? 'border-blue-400 bg-blue-50/60 text-blue-600 font-medium' : 'border-gray-200 bg-white text-gray-700 hover:border-gray-300 hover:bg-gray-50'" class="cursor-pointer rounded-xl border px-4 py-2 text-xs font-medium transition-all dark:border-slate-700 dark:bg-slate-800 dark:text-slate-200" x-text="template"></button></template></div></div><div><label for="broadcast-message" class="mb-2 block text-xs font-semibold uppercase tracking-wider text-gray-500">Message</label><div class="relative"><textarea id="broadcast-message" x-model="messageText" maxlength="1000" rows="5" placeholder="Type your announcement here..." class="w-full resize-none rounded-xl border border-gray-200 p-4 pb-8 text-sm text-gray-800 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 dark:border-slate-700 dark:bg-slate-800 dark:text-white"></textarea><span class="absolute bottom-3 right-4 text-xs font-mono" :class="messageText.length > 900 ? 'font-semibold text-amber-500' : 'text-gray-400'"><span x-text="messageText.length">0</span> / 1000</span></div></div><div class="border-t border-gray-100 pt-2 dark:border-slate-800"><button type="button" @click="sendBroadcast()" :disabled="messageText.trim() === ''" :class="messageText.trim() === '' ? 'cursor-not-allowed bg-blue-300' : 'cursor-pointer bg-blue-600 shadow-sm hover:bg-blue-700'" class="flex w-full items-center justify-center gap-2 rounded-xl py-3.5 text-sm font-medium text-white transition-all"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="m22 2-7 20-4-9-9-4 20-7Z"/><path stroke-linecap="round" stroke-linejoin="round" d="M22 2 11 13"/></svg>Send Broadcast to 8 seniors</button></div></div></section>
